import{H as e,_t as t,at as n,et as r,it as i,ot as a,rt as o,xt as s}from"./chunks/framework.Bcve9O8f.js";var c=JSON.parse(`{"title":"Compare — standards vs the local","description":"","frontmatter":{"title":"Compare — standards vs the local","head":[["meta",{"name":"robots","content":"index, follow"}],["meta",{"property":"og:title","content":"Compare — standards vs the local | Millennium Solutions"}],["meta",{"property":"og:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/compare.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Compare — standards vs the local | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/compare.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/compare.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/compare.html"}]]},"headers":[],"relativePath":"compare.md","filePath":"compare.md"}`),l={name:`compare.md`};function u(e,c,l,u,d,f){let p=s(`StandardsCompare`),m=s(`Coins`),h=s(`TokenCost`);return t(),o(`div`,null,[c[0]||=r(`h1`,{id:`compare-—-the-cryptographic-standards-and-the-local-content-address`,tabindex:`-1`},[n(`Compare — the cryptographic standards and the local content-address `),r(`a`,{class:`header-anchor`,href:`#compare-—-the-cryptographic-standards-and-the-local-content-address`,"aria-label":`Permalink to “Compare — the cryptographic standards and the local content-address”`},`​`)],-1),c[1]||=r(`blockquote`,null,[r(`p`,null,[n(`The honest question is not "which is best" — it is "what is each `),r(`strong`,null,`for`),n(`." This table puts the deposit's content-address next to the identity, hashing, authentication, and messaging standards, one factual property per column. Read the deposit's row against the others.`)])],-1),a(p),c[2]||=i(`<h2 id="what-the-table-is-saying" tabindex="-1">What the table is saying <a class="header-anchor" href="#what-the-table-is-saying" aria-label="Permalink to “What the table is saying”">​</a></h2><ul><li>The deposit&#39;s <code>toUuid</code> is a <strong>content-address</strong>, built on FNV-1a — a <strong>non-cryptographic</strong> hash by design. It is deterministic and public: anyone can recompute it with no key. That is its strength for <em>identity and integrity</em>, and exactly why it offers <strong>no</strong> secrecy.</li><li>It is <strong>not</strong> a messaging system and <strong>not</strong> encryption. For confidentiality use AES; for authentication use HMAC; for private messaging use a protocol like Signal. The deposit does not compete there — it is a different tool.</li><li>A single address <strong>cannot store</strong> an unbounded state — 128 bits is a fixed-width fingerprint, so by the pigeonhole principle it <em>references</em> a state, it does not <em>contain</em> it. You still need the data to recover it. (<a href="/millennium-solutions/theorem/lean_ledgerclaims_the_address_does_not_determine_the_payload.html">proof</a>)</li><li>Standards <strong>break</strong> — MD5 fell to collisions, SHA-1 fell (SHAttered). That is why &quot;most secure&quot; is not a claim anyone can make: security is provisional, always subject to the next cryptanalysis. And every finite digest — strong or weak — must eventually collide by pigeonhole. (<a href="/millennium-solutions/theorem/lean_ledgerclaims_more_payloads_than_addresses_must_collide.html">proof</a>)</li></ul><p>The deposit claims <strong>fitness for content-addressing</strong>, not supremacy. A content-address proves <strong>integrity, not truth</strong>.</p><h2 id="coins-vs-real-gold-vs-crypto-—-a-measure-not-a-market" tabindex="-1">Coins vs real gold vs crypto — a measure, not a market <a class="header-anchor" href="#coins-vs-real-gold-vs-crypto-—-a-measure-not-a-market" aria-label="Permalink to “Coins vs real gold vs crypto — a measure, not a market”">​</a></h2><p>Anyone chooses the <strong>terms</strong> and <strong>currency</strong>; uuidna computes, and predefines the donation amount in the URL. The reproducible measure never moves with the choice — the two coins conserve at 2, the bits count real work saved. Real gold (1 troy oz) and bitcoin (1 BTC = 100,000,000 sat) carry <strong>live market prices</strong>, fetched in your browser for measurable scale — volatile, non-reproducible, never sealed, never advice. uuidna&#39;s own value is real <strong>savings</strong> (bits of work not repeated), which at global scale become materially large (modeled, conditional on adoption). Verified by the coins are a conserved measure, not a market price and <a href="/millennium-solutions/theorem/lean_address_addressing_is_deterministic.html">anyone chooses the terms and currency</a>.</p>`,5),a(m),c[3]||=r(`h2`,{id:`cost-earnings-per-trillion-tokens-—-live-versus-uuidna`,tabindex:`-1`},[n(`Cost / earnings per trillion tokens — live, versus uuidna `),r(`a`,{class:`header-anchor`,href:`#cost-earnings-per-trillion-tokens-—-live-versus-uuidna`,"aria-label":`Permalink to “Cost / earnings per trillion tokens — live, versus uuidna”`},`​`)],-1),c[4]||=r(`p`,null,[n(`Live per-token rates for many models, fetched at view time from a credible public no-key API (OpenRouter's models endpoint), shown per `),r(`strong`,null,`trillion input tokens`),n(` — and where each stands once uuidna's content-addressing adds a caching/dedup layer. The `),r(`strong`,null,`earnings`),n(` are the compute saved on the re-addressable fraction (set the cache-hit rate), `),r(`strong`,null,`conditional, never a universal discount`),n(`. A content-address proves integrity, not truth.`)],-1),a(h)])}var d=e(l,[[`render`,u]]);export{c as __pageData,d as default};